// Gogeta-0 site renderer. Data comes from data/site-data.js (generated by tools/build_site_data.py).
(function () {
  const D = window.SITE_DATA || { devlog: [], experiments: [], generated: "" };
  const $ = (sel) => document.querySelector(sel);
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  const STATUS_LABEL = {
    planned: "Charging",
    running: "Powering up",
    done: "Fusion stable",
    failed: "Fusion failed",
    abandoned: "Abandoned",
  };
  const pill = (s) => `<span class="pill ${esc(s)}">${esc(STATUS_LABEL[s] || s)}</span>`;
  const latest = D.devlog[0];

  // ---- shared: current version badges ----
  document.querySelectorAll("[data-version]").forEach((el) => (el.textContent = latest ? latest.version : "v0"));
  document.querySelectorAll("[data-generated]").forEach((el) => (el.textContent = D.generated || "n/a"));

  // ---- landing: arcs roadmap ----
  const arcs = $("#arcs");
  if (arcs) {
    arcs.innerHTML = D.experiments
      .map(
        (e) => `
      <div class="arc${e.id === "E4" ? " milestone" : ""}">
        <div class="id">${esc(e.id)}</div>
        <div>
          <div class="name">${esc(e.arc)}${e.id === "E4" ? " · v1.0.0 milestone" : ""}</div>
          <h3><a href="experiments/${esc(e.id)}.html">${esc(e.title)}</a></h3>
          <p>${esc(e.question)}</p>
        </div>
        ${pill(e.status)}
      </div>`
      )
      .join("");
  }

  // ---- devlog: stats ----
  const stats = $("#stats");
  if (stats) {
    const count = (s) => D.experiments.filter((e) => e.status === s).length;
    const cards = [
      [latest ? latest.version : "-", "current version"],
      [D.experiments.length, "experiments"],
      [count("running"), "powering up"],
      [count("done") + " / " + count("failed"), "stable / failed"],
    ];
    stats.innerHTML = cards.map(([v, k]) => `<div class="stat-card"><div class="v">${esc(v)}</div><div class="k">${esc(k)}</div></div>`).join("");
  }

  // ---- devlog: power-level chart (val loss, lower is better) ----
  const chart = $("#chart");
  if (chart) {
    const pts = D.experiments.filter((e) => e.results && typeof e.results.val_loss === "number");
    if (!pts.length) {
      chart.innerHTML = `<div class="chart-empty"><div class="big">NO READING</div>
        <p>The scouter has nothing to measure yet. Validation loss for each finished arc shows up here.</p></div>`;
    } else {
      // Bars start just below the best result so small differences are visible (axis is not zero-based).
      const vals = pts.map((e) => e.results.val_loss);
      const max = Math.max(...vals);
      const floor = Math.min(...vals) * 0.95;
      const best = Math.min(...vals);
      chart.innerHTML =
        `<p class="kicker">Validation loss · lower is better · axis starts at ${floor.toFixed(3)}</p>` +
        pts
          .map((e) => {
            const v = e.results.val_loss;
            const w = 8 + ((v - floor) / (max - floor || 1)) * 92;
            const delta = v === best ? "best" : `+${(((v - best) / best) * 100).toFixed(1)}%`;
            return `<div class="hbar"><span>${esc(e.id)} ${esc(e.arc)}</span>
            <div class="track"><div class="fill" style="width:${w.toFixed(1)}%"></div></div>
            <b>${v.toFixed(3)} <small style="color:var(--dim)">${delta}</small></b></div>`;
          })
          .join("");
    }
  }

  // ---- devlog: experiments with filters ----
  const list = $("#experiments");
  const filters = $("#filters");
  if (list && filters) {
    const statuses = ["all", "planned", "running", "done", "failed", "abandoned"];
    let active = "all";
    const renderFilters = () => {
      filters.innerHTML = statuses
        .map((s) => {
          const n = s === "all" ? D.experiments.length : D.experiments.filter((e) => e.status === s).length;
          return `<button class="chip" data-s="${s}" aria-pressed="${s === active}">${esc(s === "all" ? "All" : STATUS_LABEL[s])} · ${n}</button>`;
        })
        .join("");
    };
    const renderList = () => {
      const rows = D.experiments.filter((e) => active === "all" || e.status === active);
      list.innerHTML = rows.length
        ? rows
            .map((e) => {
              const res = Object.entries(e.results || {});
              return `<article class="card exp">
          <div class="exp-head">
            <div><span class="id">${esc(e.id)}</span><span class="arcname">${esc(e.arc)}</span><h3>${esc(e.title)}</h3></div>
            ${pill(e.status)}
          </div>
          <p>${esc(e.question)}</p>
          <p class="prediction"><b>Prediction:</b> ${e.prediction ? esc(e.prediction) : "<i>not written yet. It must be written before the run starts.</i>"}</p>
          <div class="tags">${(e.ingredients || []).map((i) => `<span class="tag">${esc(i)}</span>`).join("")}
            ${(e.metrics || []).map((m) => `<span class="tag metric">${esc(m)}</span>`).join("")}</div>
          ${res.length ? `<div class="table-wrap"><table class="results"><tbody>${res.map(([k, v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join("")}</tbody></table></div>` : ""}
          ${e.notes ? `<p>${esc(e.notes)}</p>` : ""}
          <a class="more" href="experiments/${esc(e.id)}.html">${e.status === "done" ? "Read the breakdown & plain-English summary →" : "What this will test, in plain English →"}</a>
          <div class="meta">version: ${esc(e.version || "-")} · config: ${esc(e.config || "-")}</div>
        </article>`;
            })
            .join("")
        : `<p class="section-lede">Nothing here yet.</p>`;
    };
    filters.addEventListener("click", (ev) => {
      const b = ev.target.closest("[data-s]");
      if (!b) return;
      active = b.dataset.s;
      renderFilters();
      renderList();
    });
    renderFilters();
    renderList();
  }

  // ---- devlog: version timeline ----
  const tl = $("#timeline");
  if (tl) {
    tl.innerHTML = D.devlog
      .map(
        (v) => `<article class="card entry" id="${esc(v.version)}">
        <span class="ver">${esc(v.version)}</span><span class="date">${esc(v.date)}</span>
        <h3>${esc(v.title)}</h3>
        <div class="body">${v.html}</div>
      </article>`
      )
      .join("");
  }
})();
